export const update20261016Locales = Object.keys(rows);

/** The update of one language, checked against the English master's keys and shapes. */
export function update20261016(locale) {
  const row = rows[locale];
  if (!row) throw new Error(`Missing 16 October update translation: ${locale}`);
  for (const [k, v] of Object.entries(rows.en)) {
    const w = row[k];
    if (Array.isArray(v) ? !Array.isArray(w) || w.length !== v.length || w.some((x) => !x || !x.trim()) : typeof w !== "string" || !w.trim()) throw new Error(`16 October update: ${locale}.${k}`);
  }
  return row;
}

/** Writes the replacement strings into a dictionary; returns the new strings (new.*). */
export function applyUpdate20261016(locale, d) {
  const row = update20261016(locale);
  const fresh = {};
  for (const [path, value] of Object.entries(row)) {
    if (path.startsWith("new.")) { fresh[path.slice(4)] = value; continue; }
    const keys = path.split(".");
    let o = d;
    for (const k of keys.slice(0, -1)) {
      if (o[k] === undefined) throw new Error(`16 October update: no ${path} in ${locale}`);
      o = o[k];
    }
    o[keys.at(-1)] = Array.isArray(value) ? [...value] : value;
  }
  return fresh;
}
